from fastapi import FastAPI, Response
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/none-type", status_code=204)
def read_none() -> None:
    return None

@app.get("/none-str", status_code=204)
def read_none_str() -> "None":
    return None

client = TestClient(app)

def test_none_type():
    response = client.get("/none-type")
    assert response.status_code == 204
    assert response.text == ""

def test_none_str():
    response = client.get("/none-str")
    assert response.status_code == 204
    assert response.text == ""

if __name__ == "__main__":
    test_none_type()
    test_none_str()
    print("Tests passed!")

